export const SAFETY_SPECIFIC_CATALOG_WORKFLOW_COUNT = Object.keys(SAFETY_SPECIFIC_WORKFLOWS).length;
export const hasSafetySpecificCatalogWorkflow = (name: string): boolean => Boolean(SAFETY_SPECIFIC_WORKFLOWS[name]);
export const safetySpecificCatalogWorkflow = (name: string): TechniqueStepDefinition[] | undefined => SAFETY_SPECIFIC_WORKFLOWS[name]?.map((item) => ({ ...item }));